import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class DefaultKeyedValues_removeValue_TriageGen2Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_KeyNotFound() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);

        // Act
        // getIndex("C") should return -1, triggering the 'if (index < 0)' branch
        keyedValues.removeValue("C");

        // Assert
        assertEquals("Size should remain unchanged when key is not found", 2, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
        assertEquals("B", keyedValues.getKey(1));
    }

    @Test
    public void testRemoveValue_KeyExists() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);
        keyedValues.addValue("C", 3.0);

        // Act
        // getIndex("B") should return 1, triggering the 'removeValue(index)' call
        keyedValues.removeValue("B");

        // Assert
        assertEquals("Size should decrease by 1", 2, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
        assertEquals("C", keyedValues.getKey(1));
        // Verify value is actually gone
        assertEquals(3.0, keyedValues.getValue("C").doubleValue(), 0.001);
    }

    @Test
    public void testRemoveValue_EmptyCollection() {
        // Act
        keyedValues.removeValue("A");

        // Assert
        assertEquals(0, keyedValues.getItemCount());
    }

    @Test
    public void testRemoveValue_FirstElement() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);

        // Act
        keyedValues.removeValue("A");

        // Assert
        assertEquals(1, keyedValues.getItemCount());
        assertEquals("B", keyedValues.getKey(0));
    }

    @Test
    public void testRemoveValue_LastElement() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);

        // Act
        keyedValues.removeValue("B");

        // Assert
        assertEquals(1, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
    }
}
